/**
 * FROZEN CONTRACT (Phase 0). Builders: do not edit. Request changes in TODO.md
 * with "BLOCKED: contract change needed".
 *
 * Domain model for Rekindle. Zod schemas are the source of truth; TS types are
 * inferred. Safe to import from both server and client code (no Node APIs).
 */
import { z } from "zod";

// ---------------------------------------------------------------------------
// Primitives
// ---------------------------------------------------------------------------

const CURRENT_YEAR = new Date().getUTCFullYear();

export const Year = z.number().int().min(1880).max(CURRENT_YEAR + 1);

/** BCP 47 language tag, e.g. "en", "it", "fr", "ar-MA". Shape check only. */
export const LanguageTag = z
  .string()
  .min(2)
  .max(16)
  .regex(/^[a-zA-Z]{2,3}(-[a-zA-Z0-9]{2,8})*$/, "Expected a BCP 47 language tag");
export type LanguageTag = z.infer<typeof LanguageTag>;

/** Opaque id generated by the app (nanoid). */
export const Id = z.string().min(1).max(64);

/**
 * Qloo entity type urns (docs/qloo-api.md section 3.1). Insights-capable types
 * are in QLOO_INSIGHTS_TYPES; the rest are search-only.
 */
export const QLOO_ENTITY_TYPES = [
  "urn:entity:artist",
  "urn:entity:book",
  "urn:entity:brand",
  "urn:entity:destination",
  "urn:entity:movie",
  "urn:entity:person",
  "urn:entity:place",
  "urn:entity:podcast",
  "urn:entity:tv_show",
  "urn:entity:videogame",
  // search-only:
  "urn:entity:actor",
  "urn:entity:album",
  "urn:entity:author",
  "urn:entity:director",
  "urn:entity:locality",
] as const;
export const QlooEntityType = z.enum(QLOO_ENTITY_TYPES);
/** Types accepted by /v2/insights `filter.type`. */
export const QLOO_INSIGHTS_TYPES = [
  "urn:entity:artist",
  "urn:entity:book",
  "urn:entity:brand",
  "urn:entity:destination",
  "urn:entity:movie",
  "urn:entity:person",
  "urn:entity:place",
  "urn:entity:podcast",
  "urn:entity:tv_show",
  "urn:entity:videogame",
] as const satisfies readonly (typeof QLOO_ENTITY_TYPES)[number][];
export const QlooInsightsType = z.enum(QLOO_INSIGHTS_TYPES);
export type QlooInsightsType = z.infer<typeof QlooInsightsType>;
export type QlooEntityType = z.infer<typeof QlooEntityType>;

/**
 * Rekindle's cultural domains (what a caregiver thinks in). The mapping to
 * Qloo entity types is in TASTE_DOMAIN_QLOO_TYPES; domains with no Qloo type
 * (e.g. food as dishes) can only be llm-only.
 */
export const TASTE_DOMAINS = [
  "music",
  "film",
  "television",
  "food",
  "fashion",
  "sport",
  "public_figure",
  "book",
  "place",
] as const;
export const TasteDomain = z.enum(TASTE_DOMAINS);
export type TasteDomain = z.infer<typeof TasteDomain>;

/**
 * Which Qloo entity types can ground each domain. First entry is the preferred
 * search/insights type. Empty array: not groundable by Qloo (llm-only).
 * See docs/qloo-api.md "Implications for Rekindle".
 */
export const TASTE_DOMAIN_QLOO_TYPES: Record<TasteDomain, readonly QlooEntityType[]> = {
  music: ["urn:entity:artist", "urn:entity:album"],
  film: ["urn:entity:movie"],
  television: ["urn:entity:tv_show"],
  /** No dish type in Qloo: restaurants (place, cuisine tags) or food brands. Dishes stay llm-only. */
  food: ["urn:entity:place", "urn:entity:brand"],
  fashion: ["urn:entity:brand"],
  /** Athletes are persons; clubs appear to be brands (UNCERTAIN, see docs/qloo-api.md). */
  sport: ["urn:entity:person", "urn:entity:brand"],
  public_figure: ["urn:entity:person"],
  book: ["urn:entity:book"],
  place: ["urn:entity:destination", "urn:entity:place", "urn:entity:locality"],
};

// ---------------------------------------------------------------------------
// Input
// ---------------------------------------------------------------------------

/** What the caregiver types. Freeform `notes` is the main signal; the rest are optional hints. */
export const PersonInput = z.object({
  /** What to call them during the session ("Nonna Maria"). Never logged. */
  displayName: z.string().trim().min(1).max(60).optional(),
  /** Freeform caregiver notes. Never logged, never cached in plaintext. */
  notes: z.string().trim().min(10).max(2000),
  birthYear: Year.optional(),
  birthPlace: z.string().trim().min(1).max(120).optional(),
  /** Language the prompts are spoken in (the person's language). */
  sessionLanguage: LanguageTag.default("en"),
  /** Language of the UI, caregiver tips and prompt translations. */
  caregiverLanguage: LanguageTag.default("en"),
  /** Target session length in minutes. */
  sessionMinutes: z.number().int().min(5).max(60).default(20),
});
export type PersonInput = z.infer<typeof PersonInput>;
/** Input type before defaults are applied (what a form or API client sends). */
export type PersonInputDraft = z.input<typeof PersonInput>;

export const SessionMode = z.enum(["grounded", "llm-only"]);
export type SessionMode = z.infer<typeof SessionMode>;

// ---------------------------------------------------------------------------
// PARSE output
// ---------------------------------------------------------------------------

export const Place = z.object({
  name: z.string().min(1).max(120),
  /** ISO 3166-1 alpha-2 when known. */
  countryCode: z.string().length(2).optional(),
  role: z.enum(["birthplace", "childhood", "youth", "adulthood", "other"]),
  fromYear: Year.optional(),
  toYear: Year.optional(),
});
export type Place = z.infer<typeof Place>;

export const Love = z.object({
  label: z.string().min(1).max(120),
  domain: TasteDomain.or(z.literal("other")),
  /** "stated" if the caregiver said it, "inferred" if the LLM derived it. */
  source: z.enum(["stated", "inferred"]),
});
export type Love = z.infer<typeof Love>;

export const Sensitivity = z.object({
  /** Topic to steer away from, e.g. "the war", "late husband", "hospitals". */
  topic: z.string().min(1).max(120),
  reason: z.string().min(1).max(280),
  severity: z.enum(["avoid", "handle_gently"]),
});
export type Sensitivity = z.infer<typeof Sensitivity>;

/**
 * Life-phase labels used for cross-era retrieval. Ordered childhood through
 * later_life so a plan can span a lifespan rather than just the formative
 * window. Phase windows come from the birth year with hand-picked bounds,
 * see parse-propose::deriveLifePhases.
 */
export const LifePhaseLabel = z.enum(["childhood", "youth", "early_adulthood", "mid_life", "later_life"]);
export type LifePhaseLabel = z.infer<typeof LifePhaseLabel>;

export const LifePhase = z.object({
  label: LifePhaseLabel,
  startYear: Year,
  endYear: Year,
  /** Age range for this phase, as a short string ("8-21"). Caregiver-facing. */
  ageRange: z.string().min(1).max(16),
});
export type LifePhase = z.infer<typeof LifePhase>;

/** Structured anchors the agent reasons over. Produced by the PARSE phase. */
export const Anchors = z.object({
  birthYear: Year,
  birthYearSource: z.enum(["stated", "inferred"]),
  /** Years the person was ~10-30 (configurable): the reminiscence bump. */
  formativeWindow: z.object({ startYear: Year, endYear: Year }),
  /**
   * Full-lifespan windows (childhood through later_life) so the agent can
   * surface memories outside the formative bump: childhood lullabies, mid-life
   * television, songs they played for their own children. Optional for
   * backward compatibility; absent means fall back to formativeWindow.
   */
  lifePhases: z.array(LifePhase).max(5).optional(),
  /**
   * Hard outer bounds the person could possibly have experienced:
   * [birthYear, min(deathYear ?? currentYear, currentYear)]. Used by
   * verify-expand as a lifetime-safety rail: entities whose relevant date
   * sits outside this window are rejected with a specific reason. Optional
   * and additive; absent (no birthYear) means the check is skipped.
   */
  lifetimeWindow: z.object({ startYear: Year, endYear: Year }).optional(),
  places: z.array(Place).max(8),
  languages: z.array(z.object({ tag: LanguageTag, name: z.string().min(1).max(60) })).min(1).max(5),
  loves: z.array(Love).max(20),
  sensitivities: z.array(Sensitivity).max(10),
  occupation: z.string().max(120).optional(),
  culturalBackground: z.string().max(200).optional(),
  /** One-paragraph neutral summary for downstream prompts. Never logged. */
  summary: z.string().min(1).max(600),
});
export type Anchors = z.infer<typeof Anchors>;

// ---------------------------------------------------------------------------
// PROPOSE / VERIFY / EXPAND / CRITIQUE
// ---------------------------------------------------------------------------

/** An LLM-proposed, era/locale-plausible entity, before Qloo verification. */
export const Candidate = z.object({
  id: Id,
  domain: TasteDomain,
  name: z.string().min(1).max(160),
  /** Qloo type to search under; absent for domains Qloo cannot ground. */
  qlooType: QlooEntityType.optional(),
  /** Year it was popular / released, as the LLM believes. */
  year: Year.optional(),
  /**
   * Which life phase of the person this candidate is anchored in. Optional;
   * when present the verify/expand phases use the phase window as the era
   * filter instead of the global formative window, so a childhood lullaby
   * and a mid-life sitcom can coexist in one plan.
   */
  lifePhase: LifePhaseLabel.optional(),
  /** Why it fits this person (era, place, stated love). */
  rationale: z.string().min(1).max(400),
});
export type Candidate = z.infer<typeof Candidate>;

export const EntityProvenance = z.enum([
  /** LLM proposed it, Qloo search confirmed it exists. */
  "llm-proposed-qloo-verified",
  /** Found by Qloo cross-domain affinity from verified seeds. */
  "qloo-affinity",
]);
export type EntityProvenance = z.infer<typeof EntityProvenance>;

/** An entity confirmed to exist in Qloo, with metadata. */
export const VerifiedEntity = z.object({
  id: Id,
  qlooId: z.string().min(1).max(128),
  name: z.string().min(1).max(200),
  domain: TasteDomain,
  qlooType: QlooEntityType,
  /** Qloo affinity score (0-1), present for insights results. */
  affinity: z.number().min(0).max(1).optional(),
  /** Qloo popularity percentile (0-1) when provided. */
  popularity: z.number().min(0).max(1).optional(),
  releaseYear: Year.optional(),
  /**
   * Birth year parsed from Qloo's properties.date_of_birth (person / artist).
   * Optional and additive: surfaced on step cards and the trace so the Qloo
   * citation line can read e.g. "Qloo: born 1898". Absent means Qloo had no
   * date of birth, which is the common case for non-public_figure types.
   */
  bornYear: Year.optional(),
  /**
   * Short Qloo disambiguation line ("2022, Daniel Scheinert, Daniel Kwan").
   * Optional and additive, carried from TasteEntity so the UI citation can
   * fall back to it when there is no year or author alongside the name.
   */
  disambiguation: z.string().max(240).optional(),
  /**
   * A tiny sample of Qloo tag names (genre, decade), up to five, used by the
   * step card to render a citation for domains with no year or country field
   * (artist, destination, place). Additive and best-effort: an empty or
   * missing list means degrade and skip the citation.
   */
  tagLabels: z.array(z.string().min(1).max(80)).max(5).optional(),
  imageUrl: z.url().optional(),
  description: z.string().max(600).optional(),
  provenance: EntityProvenance,
  /** Candidate id this verified (verify phase) or seed qlooIds it came from (expand phase). */
  candidateId: Id.optional(),
  seedQlooIds: z.array(z.string()).max(10).optional(),
});
export type VerifiedEntity = z.infer<typeof VerifiedEntity>;

export const RejectionKind = z.enum([
  /** Qloo had no confident match (verify phase). */
  "not_found",
  /** Outside the person's era (critique phase, LLM judgment). */
  "anachronism",
  /** Wrong place/culture for this person (critique phase, LLM judgment). */
  "wrong_locale",
  /** Could trigger distress given sensitivities (critique phase, LLM judgment). */
  "emotional_risk",
  /** Duplicate of another item. */
  "duplicate",
  /** Weak relevance to this person. */
  "low_relevance",
]);
export type RejectionKind = z.infer<typeof RejectionKind>;

/**
 * Which guard caught this item. Additive and optional (frozen contract widened
 * for the Qloo visibility pass): the compare view credits each source
 * separately so the Devpost headline stops conflating Qloo refusals with the
 * LLM cultural-check and the critique-LLM rulings.
 *
 * - `qloo`: Qloo /search returned no confident match, or a Qloo-sourced
 *   lifetime / era filter dropped the item.
 * - `cultural-check`: the non-Western cultural grounding pass flagged a
 *   cross-cultural extrapolation.
 * - `critique-llm`: the critique LLM caught an era, locale, duplicate or
 *   sensitivity issue not detectable from Qloo alone.
 *
 * Absent on legacy events (treated as unknown).
 */
export const CatchSource = z.enum(["qloo", "cultural-check", "critique-llm"]);
export type CatchSource = z.infer<typeof CatchSource>;

export const RejectedItem = z.object({
  label: z.string().min(1).max(200),
  reason: z.string().min(1).max(400),
  kind: RejectionKind,
  phase: z.enum(["verify", "critique", "replan"]),
  domain: TasteDomain.optional(),
  /** Candidate.id or VerifiedEntity.id that was rejected. */
  refId: Id.optional(),
  /** Which guard caught the item. Optional and additive. */
  catchSource: CatchSource.optional(),
  /**
   * For `kind === "not_found"` catches with `catchSource === "qloo"`: the
   * number of /search results Qloo returned for the queried name (none of
   * which were confident matches). Powers the "checked N similar names" line.
   */
  qlooResultCount: z.number().int().min(0).optional(),
});
export type RejectedItem = z.infer<typeof RejectedItem>;

// ---------------------------------------------------------------------------
// COMPOSE output
// ---------------------------------------------------------------------------

export const StepKind = z.enum([
  /** Warm greeting, orientation, no quiz. */
  "opening",
  /** Play a song / piece. */
  "listen",
  /** Look at a photo, film still, poster, object. */
  "look",
  /** Open conversation around a theme. */
  "talk",
  /** Taste or smell something (food, coffee). */
  "taste",
  /** Gentle movement, clapping, dance from the chair. */
  "move",
  /** Calm close, gratitude. */
  "closing",
]);
export type StepKind = z.infer<typeof StepKind>;

export const StepProvenance = z.enum(["qloo-grounded", "llm-only"]);
export type StepProvenance = z.infer<typeof StepProvenance>;

export const SessionStep = z.object({
  id: Id,
  /** 0-based position in the plan. */
  order: z.number().int().min(0),
  kind: StepKind,
  title: z.string().min(1).max(120),
  /** The entity this step is built around, if any. */
  entity: VerifiedEntity.optional(),
  /** What the caregiver says aloud, in the session language. Open-ended, never a quiz. */
  prompt: z.string().min(1).max(600),
  /** Prompt translated into the caregiver language, when the two languages differ. */
  promptTranslation: z.string().max(600).optional(),
  /** Gentle follow-ups if the person engages (session language). */
  followUps: z.array(z.string().min(1).max(300)).max(4).default([]),
  /** Practical tip for the caregiver (caregiver language). */
  caregiverTip: z.string().max(300).optional(),
  durationMin: z.number().min(1).max(30),
  /** Image or media to show/play (usually entity.imageUrl). */
  mediaUrl: z.url().optional(),
  /** Hint for finding the media, e.g. "Search 'Modugno Volare 1958' on YouTube". */
  mediaHint: z.string().max(200).optional(),
  /**
   * Life phase this step is anchored in (childhood, youth, early_adulthood,
   * mid_life, later_life). Optional and additive: when present the UI shows
   * a soft phase badge so the caregiver sees the lifespan the session is
   * spanning. Absent on fallback or legacy plans.
   */
  lifePhase: LifePhaseLabel.optional(),
  provenance: StepProvenance,
});
export type SessionStep = z.infer<typeof SessionStep>;

export const SessionPlan = z.object({
  id: Id,
  title: z.string().min(1).max(160),
  /** Session (spoken) language. */
  language: LanguageTag,
  caregiverLanguage: LanguageTag,
  steps: z.array(SessionStep).min(1).max(20),
  totalMinutes: z.number().min(1).max(120),
  mode: SessionMode,
  /** Non-medical disclaimer, caregiver language. */
  disclaimer: z.string().min(1).max(600),
  generatedAt: z.iso.datetime(),
  /** Reproducibility metadata: which models, prompts and data modes produced this plan. */
  meta: z.object({
    llmProvider: z.string(),
    llmModel: z.string(),
    qlooMode: z.enum(["live", "mock", "unused"]),
    promptVersions: z.record(z.string(), z.string()),
    /** Number of replans applied to this plan. */
    revision: z.number().int().min(0).default(0),
  }),
});
export type SessionPlan = z.infer<typeof SessionPlan>;

// ---------------------------------------------------------------------------
// Adaptive loop
// ---------------------------------------------------------------------------

export const Reaction = z.enum(["lit_up", "neutral", "upset"]);
export type Reaction = z.infer<typeof Reaction>;

export const ReactionRecord = z.object({ stepId: Id, reaction: Reaction });
export type ReactionRecord = z.infer<typeof ReactionRecord>;

// ---------------------------------------------------------------------------
// API request bodies (validated by the route handlers)
// ---------------------------------------------------------------------------

export const SessionRequest = z.object({
  person: PersonInput,
  mode: SessionMode.default("grounded"),
});
export type SessionRequest = z.infer<typeof SessionRequest>;
export type SessionRequestDraft = z.input<typeof SessionRequest>;

/**
 * Stateless replan: nothing is stored server-side, so the client sends back the
 * plan, the anchors it received, and the reaction history.
 */
export const ReplanRequest = z.object({
  plan: SessionPlan,
  anchors: Anchors,
  stepId: Id,
  reaction: Reaction,
  /** Earlier reactions in this session, oldest first (excluding this one). */
  history: z.array(ReactionRecord).max(40).default([]),
  /** Optional short caregiver note ("she hummed along"). Never logged. */
  note: z.string().trim().max(280).optional(),
});
export type ReplanRequest = z.infer<typeof ReplanRequest>;
export type ReplanRequestDraft = z.input<typeof ReplanRequest>;

// ---------------------------------------------------------------------------
// Streaming events (NDJSON, one per line). See docs/api.md.
// ---------------------------------------------------------------------------

export const AgentPhase = z.enum(["parse", "propose", "verify", "expand", "critique", "compose", "replan"]);
export type AgentPhase = z.infer<typeof AgentPhase>;

const EventBase = {
  /** Monotonic sequence number within one stream, starting at 0. */
  seq: z.number().int().min(0),
  /** Milliseconds since the stream started. */
  t: z.number().min(0),
};

export const PhaseEvent = z.object({
  ...EventBase,
  type: z.literal("phase"),
  phase: AgentPhase,
  status: z.enum(["started", "completed", "skipped"]),
  /** Human-readable narration for the reasoning trace (caregiver language). */
  message: z.string().min(1).max(400),
  durationMs: z.number().min(0).optional(),
  /** Small counters for the trace, e.g. { proposed: 18 }. */
  counts: z.record(z.string(), z.number().int().min(0)).optional(),
});

/** Free-form reasoning note within a phase (short, LLM- or code-authored). */
export const NoteEvent = z.object({
  ...EventBase,
  type: z.literal("note"),
  phase: AgentPhase,
  text: z.string().min(1).max(400),
});

export const AnchorsEvent = z.object({ ...EventBase, type: z.literal("anchors"), anchors: Anchors });
export const CandidateEvent = z.object({ ...EventBase, type: z.literal("candidate"), candidate: Candidate });
export const VerifiedEvent = z.object({ ...EventBase, type: z.literal("verified"), entity: VerifiedEntity });
export const RejectedEvent = z.object({ ...EventBase, type: z.literal("rejected"), item: RejectedItem });
export const StepEvent = z.object({ ...EventBase, type: z.literal("step"), step: SessionStep });
export const PlanEvent = z.object({ ...EventBase, type: z.literal("plan"), plan: SessionPlan });

/**
 * Redacted record of one Qloo request: request-to-result provenance for the
 * trace and the submission. Params contain only cultural anchors (by the
 * TastePort contract), never personal data or the API key.
 */
export const QlooCallRecord = z.object({
  endpoint: z.enum(["/search", "/entities", "/v2/insights", "/v2/tags"]),
  /** Query params as sent (arrays comma-joined by the adapter at send time). */
  params: z.record(z.string(), z.union([z.string(), z.number(), z.boolean(), z.array(z.string())])),
  resultCount: z.number().int().min(0),
  durationMs: z.number().min(0),
  cached: z.boolean(),
  /** "mock" when served by MockQloo. */
  source: z.enum(["live", "mock"]),
});
export type QlooCallRecord = z.infer<typeof QlooCallRecord>;

export const QlooCallEvent = z.object({
  ...EventBase,
  type: z.literal("qloo_call"),
  phase: AgentPhase,
  call: QlooCallRecord,
});

export const ErrorCode = z.enum([
  "invalid_input",
  "qloo_unavailable",
  "llm_unavailable",
  "rate_limited",
  "deadline_exceeded",
  "internal",
]);
export type ErrorCode = z.infer<typeof ErrorCode>;

export const ErrorEvent = z.object({
  ...EventBase,
  type: z.literal("error"),
  code: ErrorCode,
  /** Safe, user-facing message. Never contains notes, keys or stack traces. */
  message: z.string().min(1).max(400),
  /** true: the agent degraded (e.g. fell back to llm-only) and the stream continues. */
  recoverable: z.boolean(),
  phase: AgentPhase.optional(),
});

export const DoneEvent = z.object({
  ...EventBase,
  type: z.literal("done"),
  traceId: z.string().min(1),
  durationMs: z.number().min(0),
  stats: z.object({
    candidates: z.number().int().min(0),
    verified: z.number().int().min(0),
    rejected: z.number().int().min(0),
    steps: z.number().int().min(0),
    llmCalls: z.number().int().min(0),
    qlooCalls: z.number().int().min(0),
    cacheHits: z.number().int().min(0),
  }),
});

export const AgentEvent = z.discriminatedUnion("type", [
  PhaseEvent,
  NoteEvent,
  AnchorsEvent,
  CandidateEvent,
  VerifiedEvent,
  RejectedEvent,
  StepEvent,
  PlanEvent,
  QlooCallEvent,
  ErrorEvent,
  DoneEvent,
]);
export type AgentEvent = z.infer<typeof AgentEvent>;
export type AgentEventType = AgentEvent["type"];
/** Narrow an event by its type: `AgentEventOf<"plan">`. */
export type AgentEventOf<K extends AgentEventType> = Extract<AgentEvent, { type: K }>;
/** Event without seq/t, as emitted by agent code before the stream stamps it. */
export type AgentEventPayload = AgentEvent extends infer E
  ? E extends AgentEvent
    ? Omit<E, "seq" | "t">
    : never
  : never;
